    difference = vars["v1"] - vars["v2"]
    return {
        "value": difference,
        "trace": {
            "statutory_us_rate": vars["v1"],
            "effective_income_tax_rate": vars["v2"],
            "difference": difference,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
